60	h1,h2,h3,h4{line-height:1.3;margin:1.6em 0 .6em;position:relative}
61	h1{font-size:1.9em;margin-top:.8em}
62	h2{font-size:1.45em;border-bottom:1px solid var(--line);padding-bottom:.25em}
63	h3{font-size:1.15em}
64	a{color:var(--link)}
65	a.hash{position:absolute;left:-1.1em;padding-right:.3em;color:var(--muted);text-decoration:none;opacity:0;font-weight:400}
66	h2:hover a.hash,h3:hover a.hash,h4:hover a.hash,a.hash:focus{opacity:1}
67	p,ul,ol,blockquote,pre,.table-wrap,figure,details{margin:0 0 1em}
68	blockquote{border-left:4px solid var(--quote);padding:.2em 1em;color:var(--muted)}
69	blockquote>:last-child,.callout>:last-child{margin-bottom:0}
70	code{background:var(--code);border-radius:4px;padding:.1em .35em;font:.9em ui-monospace,Consolas,monospace}
71	pre{background:var(--code);border:1px solid var(--line);border-radius:6px;padding:12px 14px;overflow-x:auto;position:relative}
72	pre code{background:none;padding:0}
73	pre.mermaid{background:none;border:0;text-align:center}
74	.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:6px}
75	.table-wrap.tall{max-height:75vh;overflow:auto}
76	table{border-collapse:collapse;min-width:100%}
77	th,td{border-bottom:1px solid var(--line);border-right:1px solid var(--line);padding:6px 10px;vertical-align:top;text-align:left}
78	th:last-child,td:last-child{border-right:0}
79	tbody tr:last-child td{border-bottom:0}
80	th{background:var(--head);position:sticky;top:0;z-index:1}
81	tbody tr:hover{background:color-mix(in srgb,var(--head) 70%,transparent)}
82	tr:has(.ref-target:target){background:var(--hl)}
83	table.meta th{width:1%;white-space:nowrap}
84	img{max-width:100%;height:auto;background:#fff;border-radius:4px}
85	figure{margin-left:0;margin-right:0;text-align:center}
86	figure img{border:1px solid var(--line);cursor:zoom-in}
87	figcaption{color:var(--muted);font-size:.9em;margin-top:.4em}
88	details{border:1px solid var(--line);border-radius:6px;padding:.4em .8em}
89	details>summary{cursor:pointer;color:var(--muted)}
90	details.code{border:0;padding:0}
91	details.code>summary{margin-bottom:.4em}
92	hr{border:0;border-top:1px solid var(--line);margin:2em 0}
93	.sec>hr:last-child,.hero>hr:last-child{display:none}
94	.tech{color:var(--muted);font-size:.92em}
95	a.xref{color:inherit;text-decoration:underline dotted color-mix(in srgb,var(--accent) 60%,transparent);text-underline-offset:3px}
96	a.xref:hover{color:var(--link)}
97	a.secref{white-space:nowrap}
98	.callout{border-left:4px solid var(--c);background:color-mix(in srgb,var(--c) 8%,transparent);border-radius:0 6px 6px 0;padding:.6em 1em;margin:0 0 1em}
99	.callout-title{font-weight:600;color:var(--c);margin:0 0 .3em}
100	.callout-note{--c:var(--note)}.callout-tip{--c:var(--tip)}.callout-important{--c:var(--important)}.callout-warning{--c:var(--warning)}.callout-caution{--c:var(--caution)}
101	.hero{padding-bottom:.5em}
102	.facts{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px;margin:0 0 1.2em;padding:0}
103	.facts>div{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:10px 14px}
104	.facts dt{font-size:.8em;color:var(--muted);text-transform:uppercase;letter-spacing:.03em}
105	.facts dd{margin:.15em 0 0}
106	.chips{display:flex;flex-wrap:wrap;gap:8px;list-style:none;padding:0;margin:0 0 1.2em}
107	.chips a{display:inline-flex;gap:.5em;align-items:baseline;border:1px solid var(--line);border-radius:999px;padding:.2em .8em;text-decoration:none;color:var(--fg);font-size:.9em}
108	.chips a:hover{border-color:var(--accent)}
109	.chips .n{color:var(--muted);font-size:.9em}
110	.toc{font-size:.9em}
111	.toc>details{border:1px solid var(--line);border-radius:8px;padding:.5em .9em;margin:16px 0}
112	.toc ol{list-style:none;margin:.3em 0;padding:0}
113	.toc ol ol{padding-left:1em}
114	.toc a{display:block;padding:.2em .5em;border-left:2px solid transparent;color:var(--muted);text-decoration:none;border-radius:0 4px 4px 0}
115	.toc a:hover{color:var(--fg);background:var(--head)}
116	.toc a.active{color:var(--fg);border-left-color:var(--accent);background:var(--head);font-weight:600}
117	@media (min-width:1100px){
118	  .layout{grid-template-columns:270px minmax(0,1fr)}
119	  .toc{position:sticky;top:56px;align-self:start;max-height:calc(100vh - 72px);overflow:auto}
120	  .toc>details{border:0;padding:0}
121	  .toc>details>summary{list-style:none;pointer-events:none;font-weight:600;color:var(--fg)}
122	}
123	.toolbar{position:sticky;top:0;z-index:5;display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:8px 20px;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(6px);border-bottom:1px solid var(--line)}
124	.toolbar .title{font-weight:600;margin-right:auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:50vw}
125	.toolbar button,.tbl-tools button,.tbl-tools input{font:inherit;font-size:.85em;color:var(--fg);background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:.25em .7em;cursor:pointer}
126	.toolbar button:hover,.tbl-tools button:hover{border-color:var(--accent)}
127	.toolbar .seg{display:inline-flex}
128	.toolbar .seg button{border-radius:0}
129	.toolbar .seg button:first-child{border-radius:6px 0 0 6px}
130	.toolbar .seg button:last-child{border-radius:0 6px 6px 0;border-left:0}
131	.toolbar button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:#fff}
132	.tbl-tools{display:flex;gap:8px;align-items:center;margin:0 0 .4em}
133	.tbl-tools input{cursor:text;min-width:12em}
134	.tbl-tools .count{color:var(--muted);font-size:.85em;margin-right:auto}
135	th.sortable{cursor:pointer;user-select:none}
136	th.sortable::after{content:"↕";opacity:.3;margin-left:.4em;font-size:.85em}
137	th[aria-sort=ascending]::after{content:"↑";opacity:.9}
138	th[aria-sort=descending]::after{content:"↓";opacity:.9}
139	button.fold{position:absolute;left:-1.6em;top:.15em;border:0;background:none;color:var(--muted);cursor:pointer;font-size:.8em;padding:.2em;transition:transform .15s}
140	.sec.collapsed>button.fold,.sec.collapsed>h2>button.fold{transform:rotate(-90deg)}
141	.sec.collapsed>:not(h2){display:none}
142	pre>button.copy{position:absolute;top:6px;right:6px;opacity:0;font-size:.75em;border:1px solid var(--line);border-radius:4px;background:var(--bg);color:var(--fg);cursor:pointer}
143	pre:hover>button.copy{opacity:1}
144	.lightbox{position:fixed;inset:0;z-index:10;background:rgba(0,0,0,.8);display:flex;align-items:center;justify-content:center;cursor:zoom-out;padding:24px}
145	.lightbox img{max-width:100%;max-height:100%;object-fit:contain}
146	body.view-functional .tech,body.view-functional [data-audience=technical]{display:none}
147	@media print{
148	  :root,:root[data-theme]{${LIGHT};color-scheme:light}
149	  @page{size:A4;margin:16mm 14mm 18mm;@bottom-right{content:counter(page) " / " counter(pages);font-size:9pt;color:#666}}
150	  body{font-size:10.5pt}
151	  .toolbar,.toc,.tbl-tools,button.fold,button.copy,a.hash{display:none!important}
152	  .layout{display:block;padding:0;max-width:none}
153	  main{max-width:none}
154	  .hero{break-after:page}
155	  .sec.collapsed>:not(h2){display:revert}
156	  .table-wrap,.table-wrap.tall{max-height:none;overflow:visible;border:0}
157	  th,td{border:1px solid #bbb}
158	  th{position:static}
159	  tr,pre,img,figure,.callout{break-inside:avoid}

