const fs=require("fs");let s=fs.readFileSync("SKILL.md","utf8");const crlf=s.includes("\r\n");s=s.replace(/\r\n/g,"\n");
const R=[
["description: Business-angle comparison of 2–5 ABAP programs that share the same business scenario but diverge by module (MM vs CO), country (KR vs EU), persona (controller vs warehouse), or time horizon. Reader = functional consultant.",
 "description: Business-angle comparison of 2–5 ABAP programs that share the same business scenario but diverge by module (MM vs CO), country (KR vs EU), persona (controller vs warehouse), or time horizon — one editable, versioned HTML report (verdict matrix, field differences, screens side by side, decision guide) plus an English companion. Reader = functional consultant."],
["analyzes them across 10 business dimensions, and emits a side-by-side Markdown comparison targeted at **functional consultants** (not developers).",
 "analyzes them across 10 business dimensions, and emits **one editable HTML report** targeted at **functional consultants** (not developers): a coloured verdict matrix with a *Differences only* switch, field-by-field differences of the selection screens and output lists, the screens drawn side by side, and a decision guide — versioned and editable like the `program-to-spec` and `program-to-manual` pages, with an English companion."],
["| [`dispatch-prompts.md`](dispatch-prompts.md) | Full `Agent(...)` prompt bodies for Steps 3, 4, 4b, 5 (kept out of workflow.md to honor the 200-line cap) |\n| [`report-template.md`](report-template.md) | Markdown report skeleton (Executive Summary → Matrix → Per-program detail → Recommendation) |",
 "| [`dispatch-prompts.md`](dispatch-prompts.md) | Full `Agent(...)` prompt bodies for Steps 3, 4, 4b, 5, 5.3 (kept out of workflow.md to honor the 200-line cap) |\n| [`render-steps.md`](render-steps.md) | Names and versions, screen drawing, the editable HTML build, review loop, English companion, import of an edited page |\n| [`report-template.md`](report-template.md) | Report skeleton (fact card → Summary → Decision guide → Matrix → Field differences → Screens → Per-program → Risks → Appendix) + comparison markup |"],
["- **Rendering (`sap-writer` × 1, Haiku)** — Step 5: renders the final Markdown using `report-template.md`. Pure formatting from structured state.",
 "- **Rendering (`sap-writer` × 1, `model: \"sonnet\"` override)** — Step 5: writes the per-program screen specs (selection / ALV), renders them, and writes the report `.md` from `report-template.md`. Sonnet because the screen specs must be transcribed 1:1 and the decision guide is consultant prose.\n- **English companion (`sap-writer` × 1, Sonnet override)** — Step 5.3, when the report language is not English (default on; the user can opt out).\n- **Main thread** builds the HTML page with `scripts/spec/md-to-html.mjs --editable` (Step 5.1) and runs the review loop."],
];
for(const [a,b] of R){if(!s.includes(a))throw a.slice(0,60);s=s.replace(a,b);}
const o=s.indexOf("<Output_Location>"),e=s.indexOf("</Output_Location>")+"</Output_Location>".length;
s=s.slice(0,o)+`<Output_Location>
\`<base>/comparisons/<NAME>-v<ver>-<lang>.html\` (the page) and \`.md\` (its source — kept for rebuilds and imports), \`<NAME>-<lang>.history.json\`, screen pictures under \`_assets/<NAME>-<lang>/<PROG>/\`, plus the same with \`-en\` for the English companion. \`<base>\` per [\`../../common/multi-profile-artifact-resolution.md\`](../../common/multi-profile-artifact-resolution.md).

- \`<NAME>\` = the program names joined by \`__vs__\` (uppercase, \`/\` → \`_\`); over 120 characters → \`compare-<hash6>\` (rule in [\`render-steps.md\`](render-steps.md) § Names).
- Versions \`1.0\`, \`1.1\`, … as in \`program-to-spec\`: a re-run of the same programs is the next minor version; a reader's page edit comes back as its own version.
</Output_Location>`+s.slice(e);
s=s.replace("This skill reads **source code + DDIC metadata + where-used + screen/GUI-status/text-element metadata** only. It does NOT call `GetTableContents` or `GetSqlQuery`.","This skill reads **source code + DDIC metadata + where-used + screen/GUI-status/text-element metadata** only. It does NOT call `GetTableContents` or `GetSqlQuery`. Sample rows in the drawn screens are invented — never business data, never real customer, vendor or company names.");
fs.writeFileSync("SKILL.md",crlf?s.replace(/\n/g,"\r\n"):s);'; grep -n "Sample rows\|render-steps\|sonnet" SKILL.md | head; wc -l *.md

