    $line
  }
  $m = $wb.Worksheets.Item(4)
  for ($r = 3; $r -le 8; $r++) { $row = @(); for ($c = 1; $c -le 5; $c++) { $cell = $m.Cells($r, $c); $row += ("{0}{{{1:X6}}}" -f ($cell.Text -replace "`n", " / "), [int]$cell.Interior.Color) }; ($row -join " | ") }
  $wb.Close($false)
} catch { "ERR: " + $_.Exception.Message } finally { $xl.Quit() }

